static BIAS: [[f64; 7]; MODELS] = [[-0.0002879453115281214, -0.00019252992139013204, 0.0005161291841231578, 0.0008720652542954124, 0.001582025876065851, 0.000706855972892558, -0.002333839535661948], [-0.00017672215750334406, -4.189638421867194e-05, 0.0004353606923056046, 0.0006183488653079059, 0.002134759402576068, 0.002032064958599274, -0.0023979919815875373], [-0.0002609677788105183, -0.00020347575198038822, 0.0002968443723755111, 0.0005741421639108922, 0.0014375843625816106, 0.0009920971124587124, -0.0021557114800660956], [-6.922072972382487e-05, 0.000254473260970211, 0.0007421212242710804, 0.0008031525692792122, 0.0021183572545351694, 0.0015097382718930654, -0.0010257312254729242], [-0.00035007005696786555, -0.0001871384273381987, 0.00039370988382208784, 0.00044994115727445527, 0.0020393870687620223, 0.001431355244722522, -0.0019665049733582946], [-0.0001751056319960872, -0.0001172442772510737, 0.00018798281817628885, 0.0009518060034358275, 0.0021417993682228517, 0.0024770289323409796, -0.0020205843539113605], [-0.0002170372721933325, -9.968693388439304e-07, 0.0005044334322040871, 0.000525566864721915, 0.0015028427844074545, 0.0007126918657014165, -0.0023336764789801965]];

use std::io::{self, BufRead, Write};

struct Decoder {
    history: [[f64; CHANNELS]; TAPS],
    cursor: usize,
}
impl Decoder {
    fn new() -> Self { Self { history: [[0.0; CHANNELS]; TAPS], cursor: 0 } }
    fn step(&mut self, input: [f64; CHANNELS], model: usize) -> [f64; 7] {
        self.history[self.cursor] = input;
        let mut rates = [0.0; CHANNELS];
        for (lag, weight) in KERNEL.iter().enumerate() {
            let row = &self.history[(self.cursor + TAPS - lag) % TAPS];
            for (rate, count) in rates.iter_mut().zip(row) { *rate += weight * count; }
        }
        self.cursor = (self.cursor + 1) % TAPS;
        let mut output = BIAS[model];
        for (rate, row) in rates.iter().zip(&WEIGHTS[model]) {
            for (value, coefficient) in output.iter_mut().zip(row) { *value += rate * coefficient; }
        }
        output
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let stdin = io::stdin();
    let mut reader = stdin.lock();
    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    let mut line = String::with_capacity(CHANNELS * 24);
    let mut decoder = Decoder::new();
    let mut model = 0;
    loop {
        line.clear();
        if reader.read_line(&mut line)? == 0 { break; }
        if line.trim().is_empty() { continue; }
        if let Some(rest) = line.trim().strip_prefix("reset ") {
            model = rest.parse::<usize>()?;
            if model >= MODELS { return Err("model index out of range".into()); }
            decoder = Decoder::new();
            continue;
        }
        let mut fields = line.split_whitespace();
        let mut counts = [0.0; CHANNELS];
        for count in &mut counts {
            *count = fields.next().ok_or("too few neural channels")?.parse::<f64>()?;
            if !count.is_finite() || *count < 0.0 { return Err("invalid neural count".into()); }
        }
        if fields.next().is_some() { return Err("too many neural channels".into()); }
        let values = decoder.step(counts, model);
        for (index, value) in values.iter().enumerate() {
            if index > 0 { write!(writer, " ")?; }
            write!(writer, "{value:.17}")?;
        }
        writeln!(writer)?;
    }
    writer.flush()?;
    Ok(())
}
